/* Original rounded maize grain/cob meshes. Kernels on an ear face radially;
   loose kernels lie on their broad side with a visible pale germ. */
(()=>{'use strict';const E=CultureEquipment,TAU=Math.PI*2,add=(a,b)=>a.map((v,i)=>v+b[i]),mul=(a,s)=>a.map(v=>v*s),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],norm=a=>mul(a,1/(Math.hypot(...a)||1));
const mix=(a,b,t)=>'#'+[1,3,5].map(i=>Math.round(parseInt(a.slice(i,i+2),16)*(1-t)+parseInt(b.slice(i,i+2),16)*t).toString(16).padStart(2,'0')).join('');
function grainMesh({width=.065,length=.085,thickness=.04,segments=12,rings=2,loose=true}={}){const point=(theta,r)=>{const v=Math.sin(theta)*r,u=Math.cos(theta)*r*(.82+.16*v),top=thickness*(.15+.85*Math.sqrt(Math.max(0,1-r*r)))-thickness*.20*Math.exp(-((u/.35)**2+((v-.40)/.32)**2));return [u*width,v*length,top]},faces=[];for(let row=0;row<rings;row++){const ra=row/rings,rb=(row+1)/rings;for(let i=0;i<segments;i++){const a=i/segments*TAU,b=(i+1)/segments*TAU;faces.push(row===0?[[0,0,thickness*.92],point(a,rb),point(b,rb)]:[point(a,ra),point(a,rb),point(b,rb),point(b,ra)])}}return {faces,point,loose}}
function kernel(w,x,y,z,{size=.1,color='#d9a544',width=size*.65,length=size*.85,thickness=size*.40,axes=null,angle=null,loose=axes===null}={}){const p=[x,y,z],scale=w.project?w.project(p).scale:80,pixels=width*scale,n=pixels>6?14:pixels>3?9:6,rings=axes?3:pixels>6?2:1,mesh=grainMesh({width,length,thickness,segments:n,rings,loose}),a=angle??Math.sin(x*71.3+z*43.7+y*19)*Math.PI,u=axes?.u||[Math.cos(a),0,Math.sin(a)],v=axes?.v||[-Math.sin(a),0,Math.cos(a)],normal=axes?.n||[0,1,0],map=q=>add(p,add(mul(u,q[0]),add(mul(v,q[1]),mul(normal,q[2]))));
for(const f of mesh.faces){const center=f.reduce((s,q)=>s.map((v,i)=>v+q[i]/f.length),[0,0,0]),shine=Math.max(0,Math.min(1,.45+center[2]/thickness*.35-center[0]/Math.max(.001,width)*.12));w.poly(f.map(map),mix(color,'#f8dea0',shine*.66),{lit:true})}
if(loose&&pixels>3){const germ=[[-.23,-.78,.46],[-.47,-.35,.72],[-.18,-.12,.86],[.08,-.30,.82],[.04,-.70,.52]].map(q=>map([q[0]*width,q[1]*length,q[2]*thickness]));w.poly(germ,'#eacb8c',{lit:false});w.line([map([-.15*width,.13*length,thickness*.91]),map([-.08*width,.46*length,thickness*.73]),map([.12*width,.62*length,thickness*.65])],'#bc8534',.45,{alpha:.5})}
}
function cob(w,x,y,z,{scale=1,husk=false,lying=false,tilt=.48}={}){const h=2.25*scale,r=.36*scale,axis=lying?norm([1,.05,.17]):norm([Math.sin(tilt),Math.cos(tilt),.08]),u=norm(cross(axis,[0,0,1])),v=cross(axis,u),center=t=>add([x,y,z],add(mul(axis,t*h),mul(u,.035*scale*Math.sin(Math.PI*t)))),radius=t=>r*Math.pow(Math.sin(Math.PI*(.10+.87*t)),.52)*(1-.24*t),at=(t,a,rr=radius(t))=>add(center(t),add(mul(u,Math.cos(a)*rr),mul(v,Math.sin(a)*rr))),sides=24,levels=30;
for(let j=0;j<levels;j++)for(let i=0;i<sides;i++){const a=i/sides*TAU,b=(i+1)/sides*TAU;w.poly([at(j/levels,a),at(j/levels,b),at((j+1)/levels,b),at((j+1)/levels,a)],'#c7a260')}
const yaw=w.current?.yaw??0,pitch=w.current?.pitch??.3,view=[Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)],rows=16;
if(!husk)for(let j=0;j<levels;j++){const t=(j+.45)/levels,rr=radius(t);for(let i=0;i<rows;i++){const a=(i+(j%2)*.025)/rows*TAU,normRad=add(mul(u,Math.cos(a)),mul(v,Math.sin(a)));if(normRad.reduce((s,x,k)=>s+x*view[k],0)<-.2)continue;const q=at(t,a,rr*.985),tangent=add(mul(u,-Math.sin(a)),mul(v,Math.cos(a)));kernel(w,...q,{width:rr*Math.PI/rows*.98,length:h/levels*.47,thickness:r*.068,color:(i+j)%4?'#dba947':'#d3a03b',axes:{u:tangent,v:axis,n:normRad}})}}
w.dot(center(.995),radius(.995)*.7,'#d4b778');w.line([center(0),add(center(0),mul(axis,-.18*scale))],'#afa17b',Math.max(1,scale*3));
if(husk){for(let leaf=0;leaf<6;leaf++){const a=leaf/6*TAU+.35,rows=16,edge=(t,side)=>at(t*.99,a+side*.62*Math.pow(Math.sin(Math.PI*(.04+.94*t)),.3),radius(t*.99)*1.08+.006*scale);for(let k=0;k<rows;k++){const t=k/rows,tt=(k+1)/rows;w.poly([edge(t,-1),edge(t,1),edge(tt,1),edge(tt,-1)],leaf%2?'#b8ab73':'#c7bb88')}w.line(Array.from({length:17},(_,i)=>at(i/16*.99,a,radius(i/16*.99)*1.10)),'#dacd9a',.55,{alpha:.7})}for(let j=0;j<10;j++){const start=center(.98),dir=add(mul(u,Math.cos(j*2.4)),mul(v,Math.sin(j*2.4)));w.line([start,add(start,add(mul(axis,.1*scale),mul(dir,.12*scale))),add(start,add(mul(axis,-.12*scale),mul(dir,.17*scale)))],'#9b8052',.55)}}
}
E.kernel=kernel;E.cornCob=cob;window.MaizeGrainGeometry={grainMesh,kernel,cob};
})();


